;/* Forms: Webflow form handling only works on Webflow hosting, so block submits until a real endpoint is wired up. */
document.addEventListener('submit', (event) => {
  const form = event.target;
  if (!form.matches('form[data-local-preview]')) return;
  event.preventDefault();
  event.stopImmediatePropagation();

  let status = form.querySelector('[role="status"]');
  if (!status) {
    status = document.createElement('p');
    status.setAttribute('role', 'status');
    form.append(status);
  }
  status.textContent = 'This form is not connected yet.';
}, true);
